{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "Ensure that 'Send Alerts To' is enabled for MSSQL servers",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The security alert policy does not specify any email addresses for sending alerts. Without this, administrators may not be promptly notified of security threats."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  disabled_alerts = [\n    \"Sql_Injection\",\n    \"Data_Exfiltration\"\n  ]\n  retention_days = 20\n  email_addresses = [\"admin@example.com\"]\n}",
  "fix_summary": "Added the 'email_addresses' property to the MSSQL server security alert policy to ensure alerts are sent to administrators."
}
